Assume that $M>C_\tau\sqrt{D\log D}$.  
	Let $(q, H)$ be  a coordinate system, for which $\left\Vert q - p \right\Vert\leq 3 \sigma$ and $ \angle_{\max} (H, T_p\mathcal{M}) \leq \alpha_0$ for some $p \in \mathcal{M}$ and $\alpha_0 = \sqrt{C_M/M}$.
	For any $\delta>0$ arbitrarily small, denote by $ \hat p_n, \widehat{T_{\hat p_n}\mathcal{M}} $ the estimates derived from Algorithm alg:step2_clean initialized with $(q,H)$ with the number of iterations $\kappa$ specified in Lemma 9.2. Then, there are $ C_{\delta,d,k} $ and $ N_{\delta} $ such that for all $ n > N_{\delta}  $ there is $\mathbf{p}\in \mathcal{M}$ for which 
	\begin{equation}
	\left\Vert \hat p_n - \mathbf p \right\Vert \leq \frac{C \ln\left(\frac{1}{\delta}\right)}{n^{r_0}}
	,\end{equation}
	and 
	\begin{equation}
	\angle_{\max}(\widehat{T_{\hat p_n}\mathcal{M}},T_{\mathbf p}\mathcal{M}) \leq C_{d}\ln\left(\frac{1}{\delta}\right) \left(\frac{ n}{\ln\left(\ln(n) \right)^2}\right)^{-r_1} = \widetilde{\mathcal{O}}(n^{-r_1})    
	\end{equation}
	with probability of at least $ 1 - \delta $, where $ r_0 = \frac{k}{2k +d} $ and where $ r_1 = \frac{k-1}{2k +d} $.

Let the conditions of Lemma 9.8 hold.
Let $g(x, \theta), \widetilde{x}(x)$ be as defined in Equation (78) and (79) respectively, let $I_d:\mathbb{R}^d\to\mathbb{R}^d$ denote the identity matrix and let $J_{\widetilde{x}_\theta}$ denote the differential of $\widetilde{x}(x)$ with respect to $x$. Then, 
\begin{equation*}
\|I_d-J_{\widetilde{x}_\theta}[0]\| = \mathcal{O}(\frac{\sigma}{\tau})
.\end{equation*}

Let the conditions of Lemma 9.9 hold, let $w(x, \widetilde{x}_\theta)$ be as defined in (96), $\widetilde{x}_\theta(x)$ be as defined in (79), and $\Delta$ as defined in (91). 
Denote by $\mathcal{D}^x_w, \mathcal{D}^{\widetilde{x}_\theta}_w$ the partial differentials of $w$ with respect to the variables $x$ and $\widetilde{x}_\theta$.
Then, for $\alpha$ smaller than some constant
\begin{equation}
    \frac{1}{2} \sigma^2 \leq \Delta(0,\widetilde{x}_\theta (0)) \leq 2 \sigma^2
,\end{equation}
\begin{equation} 
\| \mathcal{D}^{\widetilde{x}_\theta}_ w[0, \widetilde{x}_\theta(0)] \| \leq  \mathcal{O}(\sin \alpha) \qquad \|\mathcal{D}^x_w[0, \widetilde{x}_\theta(0)]\| \leq \mathcal{O}(\sin \alpha)
,\end{equation}
and
\begin{equation}
\| \mathcal{D}^{\widetilde{x}_\theta}_w[0, \widetilde{x}_\theta(0)] + \mathcal{D}^x_w[0, \widetilde{x}_\theta(0)]\| \leq \mathcal{O}(\frac{\sigma}{\tau}\sin \alpha)
.\end{equation}

Let the conditions of Lemma 9.4 hold. Let $\widetilde{x}_\theta(x)$ be as defined in equation (79) in the proof of Lemma 9.4.
Then, for any unit vector $\theta\in \mathbb{R}^{D-d}$, if $\alpha, \frac{\sigma}{\tau}$ are smaller than some constants, we have
	\begin{equation*}
	\|\widetilde{x}_\theta(0)\| \leq \sigma \sin (\alpha + 3\sqrt{\frac{\sigma}{\tau}}\alpha)
	\end{equation*}
